    let mut q = Queue::new();
    for i in 1..6 {
        q.push(i);
    }

    if let Some(front) = q.front() {
        if let Some(back) = q.back() {
            let tmp = front;
            front = back;
            back = tmp;

            while let Some(value) = q.pop() {
                println!("{}", value);
            }
        }
    }
}

